/* Public demo only: these guards simulate UX, never protect real information. */
const F=window.Finance;F.prepare(state);
let demoSession=Number(sessionStorage.getItem('kita-demo-login')||0),draftCredential=null;
const current=()=>state.people.find(p=>p.id===demoSession);
const organizer=()=>['owner','organizer'].includes(current()?.role);
const owner=()=>current()?.role==='owner';
const originalRoute=route,originalMy=myPage,originalForm=personForm,originalGallery=galleryPage,originalPhoto=photosAdmin,originalShell=adminShell,originalTransaction=transactionDetail;
function loginView(next='/my'){return frame(title('WELCOME BACK','おかえりなさい。','申込確認とフォトアルバムには、同じアカウントでログインします。')+notice+'<div class="panel"><h2>ログインの操作サンプル</h2><form id="demoLogin" data-next="'+esc(next)+'">'+field('email','メールアドレス','','email')+field('password','パスワード','','password')+'<p class="error-text" id="loginError"></p><button class="btn">ログイン →</button></form><p class="mini-note">本番は8文字以上。4桁の数字だけでは設定できません。</p><details><summary>公開サンプルのアカウント</summary><p>参加者：sample3@example.test<br>幹事：sample2@example.test<br>代表幹事：sample1@example.test<br>共通の見本パスワード：<b>Sample1987!</b></p><p>このログインは表示体験用です。実際の情報を保護する機能ではありません。</p></details></div>','narrow');}
async function credential(password,salt){const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);return Array.from(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:100000,hash:'SHA-256'},key,256))).map(v=>v.toString(16).padStart(2,'0')).join('');}
personForm=function(p={}){return originalForm(p)+applicationSchedule(state.settings)+(!editId?'<div class="panel"><h3>申込確認・アルバム用パスワード</h3>'+field('password','パスワード','','password',true,'8文字以上。見本：Sample1987!')+field('passwordConfirm','パスワード（確認）','','password')+'</div>':'');};
myPage=function(){const p=current();if(!p)return loginView();selectedPerson=p.id;let b=originalMy();const div=document.createElement('div');div.innerHTML=b;div.querySelector('[name=demoPerson]')?.closest('label')?.remove();const h=div.querySelector('.page-title p');if(h)h.textContent='本人の申込・入金状況を確認します。現在は端末内の架空データでの体験です。';return div.innerHTML+frame('<div class="panel"><h3>あなたのフォトアルバム</h3><p>登録クラス：3年'+p.class+'組</p><a class="btn" href="#/gallery/'+p.class+'">自分のクラスの写真へ ↗</a> '+(organizer()?'<a class="btn btn-outline" href="#/admin">幹事画面へ</a> ':'')+'<button class="btn btn-outline" data-feature="logout">ログアウト</button></div>');};
galleryPage=function(){const cl=Number(location.hash.split('/')[2]??current()?.class??0),photos=state.photos.filter(p=>p.published&&(!cl||!p.class||p.class===cl));return frame(title('PHOTO ALBUM','思い出を、クラスのみんなと。','申込確認と同じログインで見られるアルバムの操作見本です。')+notice+'<div class="class-tabs"><a href="#/gallery/0">すべて</a>'+Array.from({length:10},(_,i)=>'<a href="#/gallery/'+(i+1)+'" class="'+(cl===i+1?'active':'')+'">3年'+(i+1)+'組</a>').join('')+'</div>'+(state.settings.clock>state.settings.photoEnd?'<p class="panel">公開期限を過ぎています。</p>':'<div class="gallery-grid">'+albumCards(photos)+'</div>'));};
adminShell=function(section,body){let html=originalShell(section,body);const div=document.createElement('div');div.innerHTML=html;div.querySelector('.actor-select')?.remove();div.querySelector('.admin-title-row').insertAdjacentHTML('beforeend','<button class="btn btn-outline" data-feature="logout">ログアウト</button>');div.querySelector('.admin-tabs').insertAdjacentHTML('beforeend','<a href="#/admin/accounting" class="'+(section==='accounting'?'active':'')+'">会計・収支</a>'+(owner()?'<a href="#/admin/roles">幹事権限</a>':''));div.querySelector('.page-title p').textContent='ログイン中：'+current()?.name+' ／ '+(owner()?'代表幹事':'幹事')+'（公開サンプル・端末内保存）';return div.innerHTML;};
photosAdmin=function(){return originalPhoto().replace('<label class="file-drop">','<label class="field">登録先クラス<select id="photoClass"><option value="0">全体写真</option>'+Array.from({length:10},(_,i)=>'<option value="'+(i+1)+'">3年'+(i+1)+'組</option>').join('')+'</select></label><label class="file-drop">');};
function accountingPage(){F.prepare(state);const x=F.summary(state);return adminShell('accounting','<div class="stats-grid">'+[['口座入金（確認済）',x.income],['口座出金（確認済）',x.out],['口座帳簿残高（開始残高＋入出金）',x.cash],['承認済み経費・未精算',x.unpaid]].map(([k,v])=>'<div class="stat"><small>'+k+'</small><strong>'+yen(v)+'</strong></div>').join('')+'</div><div class="panel"><h2>経費・立替を記録する</h2><p>自分の経費は別の幹事が承認します。登録しただけでは銀行残高は変わりません。</p><form id="expenseForm"><div class="grid-2">'+field('date','利用日',state.settings.clock,'date')+select('category','費目',[['会場費','会場費'],['飲食費','飲食費'],['印刷費','印刷費'],['通信費','通信費'],['その他','その他']],'会場費')+field('payee','支払先')+field('amount','金額（円）','','number')+field('purpose','用途')+field('reason','登録理由')+'</div><label class="field">見本の領収書（任意・JPEG/PNG/PDF、2MBまで）<input name="receipt" type="file" accept="image/jpeg,image/png,application/pdf"></label><p class="mini-note">公開可能な架空の領収書だけを使用してください。保存はこのブラウザー内です。</p><p class="error-text" id="expenseError"></p><button class="btn">経費を申請する</button></form></div><div class="panel"><div class="section-head"><h2>経費一覧と出金照合</h2><button class="btn btn-outline" data-feature="export-finance">収支CSV ↓</button></div><p>承認済経費 '+yen(x.approved)+' ／ 出金の未照合 '+yen(x.unmatchedOut)+'。口座残高と未精算額は別の指標です。</p>'+table(['経費','申請者・支払先','費目・用途','金額 / 未精算','領収書','承認・照合'],state.expenses.map(e=>['#'+e.id+'<br>'+esc(e.date),esc(e.actor)+'<br>'+esc(e.payee),esc(e.category)+'<br>'+esc(e.purpose),yen(e.amount)+' / '+yen(e.amount-F.paid(state,e.id)),e.receipt?'<button class="link" data-feature="receipt" data-id="'+e.id+'">添付を取得</button>':'未添付',e.status==='submitted'?'<button class="link" data-feature="approve-expense" data-id="'+e.id+'">確認・承認</button>':'承認済 '+(F.paid(state,e.id)===e.amount?'・精算照合済':'<button class="link" data-feature="link-expense" data-id="'+e.id+'">出金と照合</button>')]))+'<h3>照合履歴</h3>'+table(['照合','明細 → 経費','金額','状態','操作'],state.expenseLinks.map(a=>['#'+a.id,'#'+a.transactionId+' → #'+a.expenseId,yen(a.amount),a.active?'有効':'取消済',a.active?'<button class="link" data-feature="reverse-expense" data-id="'+a.id+'">理由を付けて取消</button>':esc(a.cancelReason)]))+'</div>');}
function rolesPage(){return adminShell('roles','<div class="panel"><h2>幹事権限を管理する</h2><p>代表幹事だけが付与・解除します。申込フォームには幹事チェックを置きません。代表幹事は最後の1人を解除できません。</p>'+table(['申込番号','氏名','現在の役割','操作'],state.people.map(p=>[esc(p.number),esc(p.name),esc(p.role),p.role==='owner'?'代表幹事（この画面では変更不可）':'<button class="link" data-feature="role" data-id="'+p.id+'">'+(p.role==='organizer'?'幹事を解除':'幹事に指定')+'</button>']))+'</div>');}
transactionDetail=function(id){const t=state.transactions.find(x=>x.id===id);if(t?.debit){openModal('<h2>出金明細 #'+id+'</h2>'+details([['日付',t.date],['摘要（参考）',t.memo],['出金',yen(t.debit)],['未照合',yen(t.debit-F.debitUsed(state,id))],['注意',t.review]])+'<p>重複候補・資金化区分を確認し、経費への照合は会計画面で行います。</p>'+(t.state==='pending'?'<form id="debitForm" data-id="'+id+'">'+field('reason','確認理由')+'<button class="btn">出金を確認済みにする</button></form>':'<a class="btn" href="#/admin/accounting" onclick="closeModal()">会計・収支へ</a>'));}else originalTransaction(id);};
route=function(){F.prepare(state);const path=(location.hash.slice(1)||'/'),privatePage=/^\/(my|gallery|photo|admin|complete)(\/|$)/.test(path)||/^\/register\//.test(path);actor=current()?.name+'（サンプル）';if(privatePage&&!current()){main.innerHTML=loginView(path);return;}if(path.startsWith('/admin')&&!organizer()){main.innerHTML=frame(title('ACCESS','幹事権限が必要です。')+'<a class="btn" href="#/my">自分の申込へ</a>');return;}if(path==='/admin/roles'){main.innerHTML=owner()?rolesPage():frame(title('ACCESS','代表幹事だけが変更できます。'));return;}if(path==='/admin/accounting'){main.innerHTML=accountingPage();return;}if(/^\/(register|complete)\//.test(path)){const id=Number(path.split('/')[2]);if(id!==current()?.id){main.innerHTML=frame(title('ACCESS','本人の申込だけ確認できます。'));return;}}if(path.startsWith('/my'))selectedPerson=current().id;originalRoute();};
window.removeEventListener('hashchange',originalRoute);window.addEventListener('hashchange',route);
document.addEventListener('submit',async ev=>{const f=ev.target;if(f.id==='registrationForm'){const d=new FormData(f);try{if(!editId){const password=d.get('password');if(password.length<8||password!==d.get('passwordConfirm'))throw new Error('パスワードは8文字以上で、確認欄と同じ内容を入力してください。');if(state.people.some(p=>p.email.toLowerCase()===String(d.get('email')).toLowerCase()))throw new Error('このメールアドレスは登録済みです。');draftCredential=password;}}catch(e){ev.preventDefault();ev.stopImmediatePropagation();f.querySelector('#formError').textContent=e.message;}return;}if(!['demoLogin','expenseForm','debitForm','financeLinkForm'].includes(f.id))return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));try{if(f.id==='demoLogin'){const p=state.people.find(p=>p.email.toLowerCase()===d.email.trim().toLowerCase()),valid=p&&(p.credential?await credential(d.password,p.salt)===p.credential:d.password==='Sample1987!');if(!valid)throw new Error('メールアドレスまたはパスワードを確認してください。');demoSession=p.id;sessionStorage.setItem('kita-demo-login',p.id);selectedPerson=p.id;location.hash=f.dataset.next;route();return;}if(!organizer())throw new Error('幹事のログインが必要です。');if(f.id==='expenseForm'){let receipt=null;const file=f.elements.receipt.files[0];if(file){if(file.size>2e6||!['image/jpeg','image/png','application/pdf'].includes(file.type))throw new Error('領収書はJPEG・PNG・PDFの2MB以下にしてください。');receipt={name:file.name,uri:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);})};}change(s=>F.expense(s,{date:d.date,category:d.category,payee:d.payee,amount:Number(d.amount),purpose:d.purpose,reason:d.reason,receipt},actor));}if(f.id==='debitForm'){change(s=>F.outgoing(s,Number(f.dataset.id),actor,d.reason));closeModal();}if(f.id==='financeLinkForm'){change(s=>F.link(s,Number(d.transactionId),Number(f.dataset.id),Number(d.amount),actor,d.reason));closeModal();}route();toast('記録と操作ログを保存しました');}catch(e){const el=f.querySelector('.error-text');if(el)el.textContent=e.message;else toast(e.message);}},true);
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-feature]');if(b){ev.stopImmediatePropagation();const id=Number(b.dataset.id);try{if(b.dataset.feature==='logout'){demoSession=0;sessionStorage.removeItem('kita-demo-login');location.hash='/my';route();return;}if(!organizer())throw new Error('幹事ログインが必要です。');if(b.dataset.feature==='receipt'){const r=state.expenses.find(e=>e.id===id)?.receipt;if(r){const a=document.createElement('a');a.href=r.uri;a.download=r.name;a.click();}return;}if(b.dataset.feature==='export-finance'){download('同窓会_経費収支.csv',R.toCSV([['利用日','申請者','支払先','費目','用途','経費額','銀行出金照合額','未精算'],...state.expenses.map(e=>[e.date,e.actor,e.payee,e.category,e.purpose,e.amount,F.paid(state,e.id),e.amount-F.paid(state,e.id)])]));return;}if(b.dataset.feature==='link-expense'){const e=state.expenses.find(e=>e.id===id),ts=state.transactions.filter(t=>t.state==='confirmed'&&t.debit>F.debitUsed(state,t.id));openModal('<h2>経費 #'+id+' と出金を照合</h2><form id="financeLinkForm" data-id="'+id+'">'+select('transactionId','確認済み出金',ts.map(t=>[t.id,'#'+t.id+' '+t.date+' '+yen(t.debit-F.debitUsed(state,t.id))+' '+t.memo]),ts[0]?.id)+field('amount','照合金額',e.amount-F.paid(state,id),'number')+field('reason','照合の根拠')+'<p class="error-text"></p><button class="btn">照合を保存</button></form>');return;}const reason=prompt('処理理由を入力してください。');if(!reason?.trim())return;if(b.dataset.feature==='approve-expense')change(s=>F.approve(s,id,actor,reason));if(b.dataset.feature==='reverse-expense')change(s=>F.reverse(s,id,actor,reason));if(b.dataset.feature==='role'){if(!owner())throw new Error('代表幹事のみ操作できます。');change(s=>{const p=s.people.find(p=>p.id===id);if(p.role==='owner')throw new Error('代表幹事は変更できません。');const before=p.role;p.role=p.role==='organizer'?'participant':'organizer';R.audit(s,actor,'幹事権限変更',p.number,{role:before},{role:p.role},reason);});}route();}catch(e){toast(e.message);}return;}
 if(ev.target.closest('#confirmRegistration')&&!editId&&draftCredential){ev.preventDefault();ev.stopImmediatePropagation();const button=ev.target.closest('#confirmRegistration');button.disabled=true;try{const salt=crypto.randomUUID(),hash=await credential(draftCredential,salt);const p=change(s=>{const n=R.register(s,draft);n.role='participant';n.salt=salt;n.credential=hash;return n;});draftCredential=null;draft=null;demoSession=p.id;selectedPerson=p.id;sessionStorage.setItem('kita-demo-login',p.id);location.hash='/complete/'+p.id;}catch(e){button.disabled=false;toast(e.message);}return;}
 if(ev.target.closest('#fillDemo'))setTimeout(()=>{const f=document.querySelector('#registrationForm');if(f?.elements.password){f.elements.password.value='Sample1987!';f.elements.passwordConfirm.value='Sample1987!';}},0);
 if(ev.target.closest('[data-action]')&&location.hash.startsWith('#/admin')&&!organizer()){ev.stopImmediatePropagation();toast('幹事ログインが必要です。');}
},true);
route();
